create table if not exists public.account_erasure_requests (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, requested_at timestamptz not null default now(), status text not null default 'PENDING' check (status in ('PENDING','BLOCKED','COMPLETED','FAILED')), metadata jsonb not null default '{}'::jsonb, completed_at timestamptz);